function planReset(){WS.length=0;PLAN.months=[];PLAN.cur=null;PLAN.base=null;PLAN.fronts=[];PLAN.pref=null;clr(G.plan);clr(G.pfr);planRender();}
function ringArea2(r){let a=0;for(let i=0;i<r.length;i++){const p=r[i],q=r[(i+1)%r.length];a+=p[0]*q[1]-q[0]*p[1];}return Math.abs(a)/2;}
