/* ===== Dinding runcing (staging): sudut muka bench curam khusus front bulanan, dijaga dalam rentang yang diizinkan ===== */
function wallOv(){if(!$('epwOn')||!$('epwOn').checked)return ()=>{};const A=parseFloat($('epwA').value),a0=parseFloat($('epwA0').value),a1=parseFloat($('epwA1').value),B=parseFloat($('epwB').value),N=parseFloat($('epwN').value);if(!isFinite(A))throw new Error('Dinding runcing: isi sudut muka bench.');if((isFinite(a0)&&A<a0-1e-9)||(isFinite(a1)&&A>a1+1e-9))throw new Error('Dinding runcing: sudut muka bench '+A+'° di luar rentang yang diizinkan ('+a0+'–'+a1+'°).');if(A>90)throw new Error('Dinding runcing: sudut muka bench maksimum 90°.');
 const sv=[$('pA').value,$('pB').value,$('pN').value],ov=OVR.splice(0,OVR.length);$('pA').value=A;if(isFinite(B)&&B>=0)$('pB').value=B;if(N>=1)$('pN').value=Math.round(N);return ()=>{$('pA').value=sv[0];$('pB').value=sv[1];$('pN').value=sv[2];for(const o of ov)OVR.push(o);};}
function wallMeasure(S){/* sudut muka bench pada pit impor: pasangan string datar berbeda satu bench, jarak datar terdekat */const F=[];for(const s of S||[]){if(!s.pts||s.pts.length<3)continue;let a=1e9,b=-1e9;for(const p of s.pts){a=Math.min(a,p[2]);b=Math.max(b,p[2]);}if(b-a<0.3)F.push({z:(a+b)/2,d:densify(s.pts,1.5)});}
 const st=[],fl=[];for(const s of F)for(const t of F){const dz=t.z-s.z;if(dz<2||dz>6.5)continue;for(const p of s.d){let m=1e18;for(const q of t.d){const d=(p[0]-q[0])*(p[0]-q[0])+(p[1]-q[1])*(p[1]-q[1]);if(d<m)m=d;}m=Math.sqrt(m);if(m>dz)continue;const an=Math.atan2(dz,m)*180/Math.PI;(an>=65?st:fl).push(an);}}
 const med=a=>{if(!a.length)return NaN;a.sort((x,y)=>x-y);return a[a.length>>1];};return {steep:med(st),ns:st.length,flat:med(fl),nf:fl.length};}
