window.__PS3.PLAN=PLAN;window.__PS3.ed=()=>ED;window.__PS3.tz=(x,y)=>topoZ(x,y);window.__PS3.plan2={drop:(s_,v_,zb,w,lf)=>{planInit();PLAN.fronts.push({drop:true,s:s_||null,v:v_||null,ring:null,zb:typeof zb==='number'&&isFinite(zb)?zb:NaN,w:w>0?w:NaN,lf:lf>0?lf:NaN});planRender();},add:(ring,zb,w)=>{planInit();PLAN.fronts.push({ring,zb:typeof zb==='number'&&isFinite(zb)?zb:NaN,w:w>0?w:NaN});planRender();},pref:p=>{PLAN.pref=p;planRender();},clear:()=>{PLAN.fronts=[];planRender();},run:(zb,t,tol,auto)=>new Promise(r=>planRun(zb,t,tol,auto,(M,err)=>r(M?{sum:M.sum,vol:M.vol.tot,fr:M.fr.map(f=>({pushback:f.pushback,dbg:f.dbg,variant:f.variant,trimmed:f.trimmed,v:Math.round(f.v),d:+f.d.toFixed(1),zb:f.zb,zf:f.zf,area:Math.round(f.area),capped:f.capped,warn:f.warn})),chk:M.chk,fin:M.fin,rq:M.rq&&{len:M.rq.len,gaps:M.rq.gaps,gradeMax:M.rq.gradeMax,pieces:M.rq.pieces,ovl:M.rq.ovl},rend:M.rend,zmin:M.zmin,acc:M.acc&&M.acc.map(a=>a.ok?{ok:true,ax:a.ax&&{lenOld:Math.round(a.ax.lenOld),lenNew:Math.round(a.ax.lenNew),gOld:+(a.ax.gOld*100).toFixed(1),gNew:+(a.ax.gNew*100).toFixed(1),wOld:a.ax.wOld,old:a.ax.old},steep:a.steep,fill:+(a.fill||0).toFixed(1),len:Math.round(a.len),gmax:+(a.gmax*100).toFixed(1),z0:+a.z0.toFixed(1),zf:a.zf,path:a.path.filter((p,i)=>i%6===0)}:{ok:false,start:a.start,gap:Math.round(a.gap),at:a.at,inFront:a.inFront,zf:a.zf})}:{err}))),accept:()=>planAccept(),months:()=>PLAN.months.map(M=>({n:M.n,zbase:M.zbase,zreach:M.zreach,sum:M.sum,fr:M.fr.map(f=>({v:f.v,ring:f.ring,zb:f.zb}))})),exp:k=>planExport(k),reset:()=>planReset(),ws:()=>WS.length,dump:k=>{const M=k<0?PLAN.cur:PLAN.months[k];return M.B.map(b=>({zt:b.zt,zc:b.zc,crest:b.crest.map(ringOf),toe:b.toe.map(ringOf),roads:(b.roads||[]).map(r=>({in:r.in,out:r.out}))}));}};
